require_once dirname(dirname(__DIR__)).'/src/bootstrap.php';$user=Auth::requireRole('hospital');$hospital=current_hospital($user);$errors=[];$others=db()->prepare("SELECT h.* FROM hospitals h WHERE h.status='active' AND h.id<>? ORDER BY h.name");$others->execute([(int)$hospital['id']]);$hospitals=$others->fetchAll();if(request_method('POST')){Csrf::verify();$source=(int)($_POST['from_hospital_id']??0);$group=$_POST['blood_group']??'';$units=(int)($_POST['units_requested']??0);$urgency=$_POST['urgency']??'';$notes=trim($_POST['notes']??'');$validSource=false;foreach($hospitals as $h)if((int)$h['id']===$source)$validSource=true;if(!$validSource)$errors[]='Select a supplying hospital.';if(!in_array($group,blood_groups(),true))$errors[]='Select a valid blood group.';if($units<1||$units>1000)$errors[]='Units must be between 1 and 1000.';if(!in_array($urgency,['routine','urgent','critical'],true))$errors[]='Select urgency.';if(!$errors){db()->prepare('INSERT INTO blood_transfer_requests(from_hospital_id,to_hospital_id,blood_group,units_requested,urgency,notes,created_by) VALUES(?,?,?,?,?,?,?)')->execute([$source,(int)$hospital['id'],$group,$units,$urgency,$notes?:null,(int)$user['id']]);$id=(int)db()->lastInsertId();audit('transfer_requested','transfer',$id);flash('success','Transfer request sent to the selected hospital.');redirect('hospital/inventory.php');}}
$pageTitle='Request Blood Transfer';require dirname(dirname(__DIR__)).'/src/templates/header.php';?>
<section class="dashboard"><div class="container"><?=hospital_nav($user)?><div class="form-card" style="margin:0"><div class="eyebrow">Hospital-to-hospital coordination</div><h1>Request prototype blood transfer</h1><p class="help">The selected hospital reviews its prototype inventory before accepting. Final stock handling remains a hospital responsibility.</p><?php if($errors):?><div class="error-list"><?=e(implode(' ',$errors))?></div><?php endif;?><form method="post"><?=Csrf::field()?><div class="field"><label>Supplying hospital</label><select name="from_hospital_id" required><option value="">Select</option><?php foreach($hospitals as $h):?><option value="<?=e((string)$h['id'])?>"><?=e($h['name'])?> · <?=e($h['district'])?></option><?php endforeach;?></select></div><div class="form-grid"><div class="field"><label>Blood group</label><select name="blood_group"><?php foreach(blood_groups() as $g):?><option><?=e($g)?></option><?php endforeach;?></select></div><div class="field"><label>Units requested</label><input type="number" name="units_requested" min="1" max="1000" required></div><div class="field"><label>Urgency</label><select name="urgency"><option value="routine">Routine</option><option value="urgent" selected>Urgent</option><option value="critical">Critical</option></select></div></div><div class="field"><label>Coordination note</label><textarea name="notes" maxlength="500"></textarea></div><button class="btn">Send Transfer Request</button></form></div></div></section>
